var IND = null;
function decodeIndustryData(b64str) {
  var binaryStr = atob(b64str);
  var bytes = new Uint8Array(binaryStr.length);
  for (var i = 0; i < binaryStr.length; i++) bytes[i] = binaryStr.charCodeAt(i);
  var ds = new DecompressionStream('gzip');
  var stream = new Blob([bytes]).stream().pipeThrough(ds);
  return new Response(stream).blob().then(function(b) { return b.text(); }).then(function(text) { return JSON.parse(text); });
}


var SQ = String.fromCharCode(39);
var selectedIndustry = null;
var allInds = [];

function buildGrid(filter){
filter = (filter||'').toLowerCase();
var grid = document.getElementById('industryGrid');
var list = filter ? allInds.filter(function(i){return i.label.toLowerCase().indexOf(filter)>=0||i.key.indexOf(filter)>=0;}) : allInds;
grid.innerHTML = list.map(function(i){
var sel = (selectedIndustry===i.key) ? " selected" : "";
var html = '<div class="ind-tile' + sel + '" onclick="selectInd(' + SQ + i.key + SQ + ')">';
html += '<span class="icon">' + i.icon + '</span>' + i.label + '</div>';
return html;
}).join("");
}
async function initIndustryData() {
IND = await decodeIndustryData(IND_B64_GZ);
allInds = Object.entries(IND).filter(function(e){return e[0]!=='other';}).map(function(e){return{key:e[0],label:e[1].label,icon:e[1].icon};});
buildGrid();
return IND;
}
var industryDataReady = initIndustryData();
document.getElementById('indSearch').addEventListener('input',function(){buildGrid(this.value);});

function selectInd(key){
selectedIndustry=key;
buildGrid(document.getElementById('indSearch').value);
document.getElementById('otherInput').classList.toggle('hidden',key!=='other');
document.getElementById('btnInd').disabled=false;
}

function buildHours(){
var days=[['monday','Monday'],['tuesday','Tuesday'],['wednesday','Wednesday'],['thursday','Thursday'],['friday','Friday'],['saturday','Saturday'],['sunday','Sunday']];
var def={monday:'8:00 AM - 5:00 PM',tuesday:'8:00 AM - 5:00 PM',wednesday:'8:00 AM - 5:00 PM',thursday:'8:00 AM - 5:00 PM',friday:'8:00 AM - 5:00 PM',saturday:'9:00 AM - 2:00 PM',sunday:''};
var on={monday:true,tuesday:true,wednesday:true,thursday:true,friday:true,saturday:true,sunday:false};
document.getElementById('hoursContainer').innerHTML=days.map(function(pair){
var d=pair[0],l=pair[1];
var chk = on[d] ? ' checked' : '';
var hide = on[d] ? '' : ' style="display:none"';
var html = '<div class="hours-row">';
html += '<label class="hours-check">';
html += '<input type="checkbox" name="day_' + d + '"' + chk + ' onchange="toggleDay(\'' + d + '\')">';
html += ' ' + l + '</label>';
html += '<div id="ht_' + d + '"' + hide + '>';
html += '<input type="text" name="hours_' + d + '" value="' + def[d] + '" placeholder="e.g. 8:00 AM - 5:00 PM" style="padding:8px 12px;border:2px solid #e5e7eb;border-radius:8px;font-size:14px;font-family:inherit;width:100%;outline:none" onfocus="this.style.borderColor=\'#0066FF\'" onblur="this.style.borderColor=\'#e5e7eb\'">';
html += '</div></div>';
return html;
}).join('');
}
function toggleDay(d){var el=document.getElementById('ht_'+d);var chk=document.querySelector('[name="day_'+d+'"]');if(el)el.style.display=chk.checked?'':'none';}
buildHours();

function buildServices(key){
var d=IND[key]||IND['other'];
document.getElementById('svcTitle').textContent=d.label+' — Services & Pricing';
document.getElementById('svcContainer').innerHTML='<div class="svc-grid">'+
d.services.map(function(s){
var k=s.toLowerCase().replace(/[^a-z0-9]/g,'_');
return '<div class="svc-item"><input type="checkbox" name="service_'+k+'" id="sv_'+k+'" value="on"><label for="sv_'+k+'">'+s+'</label><input type="text" class="svc-price" name="price_'+k+'" placeholder="Price"></div>';
}).join('')+'</div>';
if(d.questions&&d.questions.length){
var qh='<div class="ind-qs"><p class="ind-qs-title">&#128203; A few questions specific to your industry:</p>';
d.questions.forEach(function(q){
qh+='<div class="field"><label>'+q.l+'</label>';
if(q.t==='radio'){
qh+='<div class="radio-group">';
q.o.forEach(function(opt){qh+='<label class="radio-item"><input type="radio" name="'+q.n+'" value="'+opt.replace(/"/g,"&quot;")+'"> '+opt+'</label>';});
qh+='</div>';
} else if(q.t==='checkbox'){
qh+='<div class="checkbox-group">';
q.o.forEach(function(opt){
var cbId='cb_'+q.n+'_'+opt.replace(/[^a-z0-9]/gi,'_');
qh+='<label class="checkbox-item" id="lbl_'+cbId+'"><input type="checkbox" id="'+cbId+'" name="'+q.n+'_cb" value="'+opt.replace(/"/g,"&quot;")+'"> '+opt+'</label>';
});
qh+='</div>';
} else if(q.t==='textarea'){
qh+='<textarea name="'+q.n+'" placeholder="'+(q.p||'').replace(/"/g,"&quot;")+'"></textarea>';
} else {
qh+='<input type="text" name="'+q.n+'" placeholder="'+(q.p||'').replace(/"/g,"&quot;")+'">';
}
qh+='</div>';
});
qh+='</div>';
document.getElementById('indQuestions').innerHTML=qh;
} else {
document.getElementById('indQuestions').innerHTML='';
}
}

