var CF_BASE2 = "https://api.cloudflare.com/client/v4";
async function cfHash(contentBytes, relPath) {
  const ext = relPath.includes(".") ? relPath.split(".").pop() : "";
  const base64 = btoa(String.fromCharCode(...contentBytes));
  const fullHash = await blake3(base64 + ext);
  return fullHash.slice(0, 32);
}
