async function ensureProject(env, projectName) {
  const checkRes = await fetch(`${CF_BASE2}/accounts/${env.CF_ACCOUNT_ID}/pages/projects/${projectName}`, {
    headers: { Authorization: `Bearer ${env.CF_API_TOKEN}` }
  });
  if (checkRes.ok) return;
  const createRes = await fetch(`${CF_BASE2}/accounts/${env.CF_ACCOUNT_ID}/pages/projects`, {
    method: "POST",
    headers: { Authorization: `Bearer ${env.CF_API_TOKEN}`, "Content-Type": "application/json" },
    body: JSON.stringify({ name: projectName, production_branch: "main" })
  });
  const createData = await createRes.json();
  if (!createRes.ok) throw new Error("CF Pages create failed: " + JSON.stringify(createData.errors));
  await new Promise((r) => setTimeout(r, 3e3));
}
