async function generateAndDeployBlog(env, db, client2, postCount = 30) {
  if (!planIncludesBlog(client2)) {
    console.log(`[blog-generator] Plan does not include blog for ${client2.data.businessName} \u2014 skipping`);
    return;
  }
  if (!client2.cfProjectName) {
    console.warn("[blog-generator] No cfProjectName \u2014 skipping");
    return;
  }
  const topics = buildTopics(client2, postCount);
  const posts = [];
  for (let i = 0; i < topics.length; i++) {
    try {
      const post = await generateBlogPost(env, client2, topics[i], i + 1);
      posts.push(post);
      if (i < topics.length - 1) await new Promise((r) => setTimeout(r, 800));
    } catch (err) {
      console.error(`[blog-generator] Failed to generate post ${i + 1}:`, err.message);
    }
  }
  if (posts.length === 0) {
    console.error("[blog-generator] No posts generated \u2014 aborting deploy");
    return;
  }
  const blogFiles = {};
  blogFiles["blog/index"] = buildBlogIndexHTML(posts, client2);
  posts.forEach((post) => {
    blogFiles[`blog/${post.slug}`] = buildPostHTML(post, client2, posts);
  });
  await deployToCloudflarePages(env, client2.cfProjectName, blogFiles);
  const newData = {
    ...client2.data,
    blogPosts: posts.map((p) => ({ slug: p.slug, title: p.title, publishDate: p.publishDate, postNumber: p.postNumber })),
    blogGeneratedAt: (/* @__PURE__ */ new Date()).toISOString(),
    blogPostCount: posts.length
  };
  await saveClient(db, { ...client2, data: newData });
  console.log(`[blog-generator] Blog deployed for ${client2.data.businessName} \u2014 ${posts.length} posts`);
}
