async function generateMonthlyBlogPosts(env, db, client2) {
  if (!planIncludesBlog(client2)) return;
  if (!client2.cfProjectName) return;
  const existingCount = client2.data.blogPostCount || 0;
  const newCount = 8;
  const allTopics = buildTopics(client2, existingCount + newCount);
  const newTopics = allTopics.slice(existingCount, existingCount + newCount);
  const newPosts = [];
  for (let i = 0; i < newTopics.length; i++) {
    try {
      const post = await generateBlogPost(env, client2, newTopics[i], existingCount + i + 1);
      newPosts.push(post);
      if (i < newTopics.length - 1) await new Promise((r) => setTimeout(r, 800));
    } catch (err) {
      console.error(`[blog-generator] Monthly post ${i + 1} failed:`, err.message);
    }
  }
  if (newPosts.length === 0) return;
  const existingMeta = client2.data.blogPosts || [];
  const allPosts = [...existingMeta.map((p) => ({ ...p, content: "", metaDescription: p.title })), ...newPosts];
  const blogFiles = {};
  blogFiles["blog/index"] = buildBlogIndexHTML(allPosts, client2);
  newPosts.forEach((post) => {
    blogFiles[`blog/${post.slug}`] = buildPostHTML(post, client2, allPosts);
  });
  await deployToCloudflarePages(env, client2.cfProjectName, blogFiles);
  const newData = {
    ...client2.data,
    blogPosts: [...existingMeta, ...newPosts.map((p) => ({ slug: p.slug, title: p.title, publishDate: p.publishDate, postNumber: p.postNumber }))],
    blogPostCount: existingMeta.length + newPosts.length,
    blogLastUpdated: (/* @__PURE__ */ new Date()).toISOString()
  };
  await saveClient(db, { ...client2, data: newData });
  console.log(`[blog-generator] Monthly update complete for ${client2.data.businessName} \u2014 ${newPosts.length} new posts`);
}
