// Never blocks or fails the calling action — logging errors are swallowed.
async function logActivity(env, clientId, action, details) {
  const logDb = getDb(env);
  try {
    await logDb.connect();
    await logDb.query(
      `INSERT INTO activity_log (client_id, action, details) VALUES ($1, $2, $3)`,
      [clientId || null, action, details || null]
    );
  } catch (err) {
    console.error("[activity_log]", action, err.message);
  } finally {
    await closeDb(logDb);
  }
}
