admin.post("/api/admin/set-status", async (c) => {
  if (!checkAdmin(c)) return c.json({ error: "Unauthorized" }, 403);
  const { clientId, newStatus } = await c.req.json();
  if (!clientId || !newStatus) return c.json({ error: "clientId and newStatus required" }, 400);
  if (!["active", "suspended", "pending"].includes(newStatus)) return c.json({ error: "Invalid status" }, 400);
  const db = getDb(c.env);
  try {
    await db.connect();
    const result = await db.query(`SELECT * FROM clients WHERE id = $1`, [clientId]);
    if (result.rows.length === 0) return c.json({ error: "Client not found" }, 404);
    const client2 = result.rows[0];
    const oldStatus = client2.status;
    let finalStatus = newStatus;
    let telephonyEnabled = client2.telephony_enabled;
    let redeployNote = null;
    if (newStatus === "suspended") {
      telephonyEnabled = false;
    } else if (newStatus === "active" && oldStatus === "suspended") {
      finalStatus = "pending";
      if (client2.twilio_number) telephonyEnabled = true;
      if (client2.cf_project_name) {
        try {
          await redeployLive(c.env, db, client2);
          finalStatus = "active";
        } catch (e) {
          console.error("[set-status] Redeploy failed:", e.message);
          redeployNote = "Reactivation redeploy failed: " + e.message;
        }
      }
    }
    await db.query(
      `UPDATE clients SET status = $1, telephony_enabled = $2, updated_at = NOW() WHERE id = $3`,
      [finalStatus, telephonyEnabled, clientId]
    );
    c.executionCtx.waitUntil(logActivity(c.env, clientId, "set_status", `${oldStatus} \u2192 ${finalStatus}${redeployNote ? " (" + redeployNote + ")" : ""}`));
    c.executionCtx.waitUntil(
      sendEmail(c.env, {
        to: ADMIN_EMAIL,
        subject: `\u{1F504} Status Change: ${client2.data?.businessName} \u2014 ${oldStatus} \u2192 ${finalStatus}`,
        html: `<p><strong>${client2.data?.businessName}</strong> status changed from <strong>${oldStatus}</strong> to <strong>${finalStatus}</strong>.</p>`
      }).catch(() => {
      })
    );
    return c.json({ success: true, oldStatus, newStatus: finalStatus, note: redeployNote });
  } finally {
    await closeDb(db);
  }
});
admin.post("/api/admin/update-client", async (c) => {
  if (!checkAdmin(c)) return c.json({ error: "Unauthorized" }, 403);
  const { clientId, fields, redeploy } = await c.req.json();
  if (!clientId || !fields) return c.json({ error: "clientId and fields required" }, 400);
  const db = getDb(c.env);
  try {
    await db.connect();
    const result = await db.query(`SELECT * FROM clients WHERE id = $1`, [clientId]);
    if (result.rows.length === 0) return c.json({ error: "Client not found" }, 404);
    const client2 = result.rows[0];
    const BLOCKED = ["id", "dashToken", "dashPassword", "previewToken", "_previewToken"];
    const newData = { ...client2.data };
    let changed = 0;
    Object.keys(fields).forEach((k) => {
      if (!BLOCKED.includes(k) && fields[k] !== void 0) {
        newData[k] = fields[k];
        changed++;
      }
    });
    await db.query(`UPDATE clients SET data = $1, updated_at = NOW() WHERE id = $2`, [JSON.stringify(newData), clientId]);
    c.executionCtx.waitUntil(logActivity(c.env, clientId, "update_client", `Updated ${changed} field(s): ${Object.keys(fields).join(", ")}`));
    let redeployNote = null;
    if (redeploy && client2.status === "active" && client2.cf_project_name) {
      try {
        await redeployLive(c.env, db, { ...client2, data: newData });
      } catch (e) {
        console.error("[admin/update-client] Redeploy failed:", e.message);
        return c.json({ success: true, changed, redeployed: false, redeployError: e.message });
      }
    }
    return c.json({ success: true, changed, redeployed: !!(redeploy && client2.status === "active" && client2.cf_project_name), note: redeployNote });
  } finally {
    await closeDb(db);
  }
});
admin.post("/api/admin/bind-domain", async (c) => {
  if (!checkAdmin(c)) return c.json({ error: "Unauthorized" }, 403);
  const { clientId, customDomain } = await c.req.json();
  if (!clientId || !customDomain) return c.json({ error: "clientId and customDomain are required" }, 400);
  const db = getDb(c.env);
  try {
    await db.connect();
    const result = await db.query(`SELECT * FROM clients WHERE id = $1`, [clientId]);
    if (result.rows.length === 0) return c.json({ error: "Client not found" }, 404);
    const client2 = result.rows[0];
    if (!client2.cf_project_name) return c.json({ error: "Client has no CF Pages project yet \u2014 deploy first" }, 400);
    if (!c.env.CF_ACCOUNT_ID || !c.env.CF_API_TOKEN) return c.json({ error: "CF credentials not configured" }, 500);
    const cleanDomain = customDomain.replace(/^https?:\/\//, "").trim();
    const cfRes = await fetch(
      `https://api.cloudflare.com/client/v4/accounts/${c.env.CF_ACCOUNT_ID}/pages/projects/${client2.cf_project_name}/domains`,
      {
        method: "POST",
        headers: { Authorization: `Bearer ${c.env.CF_API_TOKEN}`, "Content-Type": "application/json" },
        body: JSON.stringify({ name: cleanDomain })
      }
    );
    const cfData = await cfRes.json();
    if (!cfRes.ok) return c.json({ error: "CF API error", details: cfData.errors }, 502);
    const newData = { ...client2.data, customDomain };
    const liveUrl = `https://${cleanDomain}`;
    await db.query(`UPDATE clients SET data = $1, live_url = $2, updated_at = NOW() WHERE id = $3`, [
      JSON.stringify(newData),
      liveUrl,
      clientId
    ]);
    c.executionCtx.waitUntil(logActivity(c.env, clientId, "bind_domain", `Bound custom domain ${customDomain}`));
    return c.json({ success: true, customDomain, liveUrl });
  } catch (err) {
    console.error("[bind-domain]", err.message);
    return c.json({ error: "Bind domain failed: " + err.message }, 500);
  } finally {
    await closeDb(db);
  }
});
