// ── Stage C: Revenue Pipeline (all partners at once) ──
admin.get("/api/admin/revenue-pipeline", async (c) => {
  if (!checkAdmin(c)) return c.json({ error: "Unauthorized" }, 403);
  const db = getDb(c.env);
  try {
    await db.connect();
    const partnersResult = await db.query(
      `SELECT id, full_name, email, tier, territory_name, territory_type FROM territory_partner_applications WHERE status = 'approved' ORDER BY full_name`
    );
    const clientsResult = await db.query(
      `SELECT partner_id, data->>'partnerId' AS json_partner_id, data->>'selectedPlan' AS selected_plan, data->>'plan' AS plan
       FROM clients WHERE partner_id IS NOT NULL OR data->>'partnerId' IS NOT NULL`
    );
    const planPrices2 = {
      "website-only": 99, website_only: 99, "Website Only": 99,
      "website-blog": 129, website_blog: 129, "Website + Blog": 129,
      "website-blog-social": 159, "Website + Blog + Social": 159,
      "full-package": 218, "Full Package": 218
    };
    // NOTE: this assumes the standard 60% partner split for everyone.
    // At least one partner (Madison, founding rep) has a different
    // documented rate (80/20) stored only as free text in the notes
    // column, not a structured rate field, so her numbers below will
    // be understated until that's tracked properly.
    const pipeline = partnersResult.rows.map((p) => {
      const theirClients = clientsResult.rows.filter(
        (row) => String(row.partner_id) === String(p.id) || String(row.json_partner_id) === String(p.id)
      );
      const totalMRR = theirClients.reduce((s, row) => {
        const plan = row.selected_plan || row.plan || "";
        return s + (planPrices2[plan] || 0);
      }, 0);
      return {
        partnerId: p.id,
        name: p.full_name,
        email: p.email,
        tier: p.tier,
        territoryName: p.territory_name,
        territoryType: p.territory_type,
        clientCount: theirClients.length,
        totalMRR,
        partnerMRR: Math.round(totalMRR * 0.6)
      };
    });
    const grandTotalMRR = pipeline.reduce((s, p) => s + p.totalMRR, 0);
    const grandTotalPartnerMRR = pipeline.reduce((s, p) => s + p.partnerMRR, 0);
    return c.json({ partners: pipeline, grandTotalMRR, grandTotalPartnerMRR });
  } catch (err) {
    console.error("[admin/revenue-pipeline]", err.message);
    return c.json({ error: "Failed to load revenue pipeline" }, 500);
  } finally {
    await closeDb(db);
  }
});
// ── Stage D: Churn Risk ──
// Flags a client if BOTH: (a) zero pageviews/bookings in the last 30 days
// AND (b) their most recent billing event is a failure, OR they have no
// successful billing event at all despite being an active client.
admin.get("/api/admin/churn-risk", async (c) => {
  if (!checkAdmin(c)) return c.json({ error: "Unauthorized" }, 403);
  const db = getDb(c.env);
  try {
    await db.connect();
    const clientsResult = await db.query(
      `SELECT id, data->>'businessName' AS business_name, status FROM clients WHERE status = 'active'`
    );
    const activityResult = await db.query(
      `SELECT client_id, COUNT(*) AS recent_activity
       FROM analytics_events
       WHERE created_at >= NOW() - INTERVAL '30 days'
         AND event_type IN ('pageview', 'booking')
       GROUP BY client_id`
    );
    const activityMap = {};
    activityResult.rows.forEach((r) => {
      activityMap[r.client_id] = parseInt(r.recent_activity, 10);
    });
    const billingResult = await db.query(
      `SELECT DISTINCT ON (client_id) client_id, event_type, status, created_at
       FROM billing_events ORDER BY client_id, created_at DESC`
    );
    const billingMap = {};
    billingResult.rows.forEach((r) => {
      billingMap[r.client_id] = r;
    });
    const atRisk = clientsResult.rows.filter((c2) => {
      const noRecentActivity = !activityMap[c2.id] || activityMap[c2.id] === 0;
      const latestBilling = billingMap[c2.id];
      const paymentIssue = latestBilling ? latestBilling.event_type === "invoice.payment_failed" : false;
      return noRecentActivity || paymentIssue;
    }).map((c2) => ({
      clientId: c2.id,
      businessName: c2.business_name || "(unnamed)",
      reasons: [
        (!activityMap[c2.id] || activityMap[c2.id] === 0) ? "No site visits or bookings in 30 days" : null,
        billingMap[c2.id]?.event_type === "invoice.payment_failed" ? "Most recent payment failed" : null
      ].filter(Boolean)
    }));
    return c.json({ atRiskCount: atRisk.length, clients: atRisk });
  } catch (err) {
    console.error("[admin/churn-risk]", err.message);
    return c.json({ error: "Failed to load churn risk" }, 500);
  } finally {
    await closeDb(db);
  }
});
