admin.post("/api/coming-soon", async (c) => {
  if (!checkAdmin(c)) return c.json({ error: "Unauthorized" }, 403);
  const { action, id, name, description, category } = await c.req.json();
  const db = getDb(c.env);
  try {
    await db.connect();
    if (action === "add") {
      await db.query(`INSERT INTO coming_soon_features (id, name, description, category) VALUES ($1,$2,$3,$4)`, [
        "feat_" + Date.now(),
        name,
        description,
        category || "New Feature"
      ]);
    } else if (action === "edit") {
      await db.query(`UPDATE coming_soon_features SET name=$1, description=$2, category=$3 WHERE id=$4`, [
        name,
        description,
        category || "New Feature",
        id
      ]);
    } else if (action === "delete") {
      await db.query(`DELETE FROM coming_soon_features WHERE id=$1`, [id]);
    }
    const result = await db.query(`SELECT * FROM coming_soon_features ORDER BY sort_order ASC, created_at ASC`);
    return c.json({
      features: result.rows.map((r) => ({
        id: r.id,
        name: r.name,
        description: r.description,
        category: r.category,
        ratingSum: r.rating_sum,
        totalRatings: r.total_ratings
      }))
    });
  } catch (err) {
    console.error("[coming-soon POST]", err);
    return c.json({ error: "Failed" }, 500);
  } finally {
    await closeDb(db);
  }
});
admin.get("/api/admin/check-token", async (c) => {
  if (!checkAdmin(c)) return c.json({ error: "Unauthorized" }, 403);
  const token = c.req.query("t");
  if (!token) return c.json({ error: "Missing query param: t (preview token)" }, 400);
  const db = getDb(c.env);
  try {
    await db.connect();
    const totalResult = await db.query(`SELECT COUNT(*) AS count FROM clients`);
    const totalClients = parseInt(totalResult.rows[0].count);
    const match2 = await db.query(`SELECT * FROM clients WHERE preview_token = $1`, [token]);
    if (match2.rows.length === 0) {
      const allTokens = await db.query(`SELECT id, data, preview_token FROM clients`);
      return c.json({
        found: false,
        totalClientsInMemory: totalClients,
        allTokens: allTokens.rows.map((r) => ({ id: r.id, businessName: r.data?.businessName || null, previewToken: r.preview_token || null })),
        hint: "No client has this previewToken."
      });
    }
    const m = match2.rows[0];
    return c.json({
      found: true,
      totalClientsInMemory: totalClients,
      client: {
        id: m.id,
        businessName: m.data?.businessName || null,
        ownerName: m.data?.ownerName || null,
        email: m.data?.email || null,
        status: m.status,
        previewToken: m.preview_token,
        dashPassword: m.dash_password || null,
        dashToken: m.dash_token || null,
        liveUrl: m.live_url || null,
        cfProjectName: m.cf_project_name || null,
        createdAt: m.created_at || null,
        approvedAt: m.approved_at || null,
        hasData: !!m.data,
        dataKeys: m.data ? Object.keys(m.data) : [],
        telephonyEnabled: m.telephony_enabled || false,
        twilioNumber: m.twilio_number || null
      }
    });
  } finally {
    await closeDb(db);
  }
});
admin.post("/api/admin/generate-blog", async (c) => {
  if (!checkAdmin(c)) return c.json({ error: "Unauthorized" }, 403);
  const { clientId, postCount, force } = await c.req.json();
  if (!clientId) return c.json({ error: "clientId required" }, 400);
  const db = getDb(c.env);
  try {
    await db.connect();
    const result = await db.query(`SELECT * FROM clients WHERE id = $1`, [clientId]);
    if (result.rows.length === 0) return c.json({ error: "Client not found" }, 404);
    const client2 = clientFromRow(result.rows[0]);
    if (!client2.cfProjectName) return c.json({ error: "Client has no CF Pages project \u2014 must be deployed first" }, 400);
    if (!force && !planIncludesBlog(client2)) {
      return c.json({ error: `Client plan (${client2.data.selectedPlan || "none"}) does not include blog. Pass force:true to override.` }, 400);
    }
    const count = parseInt(postCount) || 30;
    c.executionCtx.waitUntil(
      generateAndDeployBlog(c.env, db, client2, count).then(() => {
        console.log(`[admin/generate-blog] Complete for ${client2.data.businessName}`);
        logActivity(c.env, clientId, "generate_blog", `Generated ${count} posts`);
        return sendEmail(c.env, {
          to: ADMIN_EMAIL,
          subject: `\u{1F4DD} Blog Generated: ${client2.data.businessName}`,
          html: `<p><strong>${client2.data.businessName}</strong> blog complete \u2014 ${count} posts at <a href="${client2.liveUrl}/blog/index.html">${client2.liveUrl}/blog/index.html</a></p>`
        }).catch(() => {
        });
      }).catch((err) => {
        console.error(`[admin/generate-blog] Failed for ${client2.data.businessName}:`, err.message);
        logActivity(c.env, clientId, "generate_blog_failed", err.message);
        return sendEmail(c.env, {
          to: ADMIN_EMAIL,
          subject: `\u274C Blog Generation Failed: ${client2.data.businessName}`,
          html: `<p>Blog generation failed for <strong>${client2.data.businessName}</strong>: ${err.message}</p>`
        }).catch(() => {
        });
      }).finally(() => closeDb(db))
    );
    return c.json({ success: true, message: `Blog generation started for ${client2.data.businessName} \u2014 ${count} posts.`, clientId, postCount: count });
  } catch (err) {
    console.error("[admin/generate-blog]", err);
    await closeDb(db);
    return c.json({ error: "Failed to start blog generation: " + err.message }, 500);
  }
});
