    const result = await db.query(`SELECT * FROM clients WHERE id = $1`, [id]);
    if (result.rows.length === 0) return c.text("Not found", 404);
    const row = result.rows[0];
    if (row.preview_token !== token) return c.text("Invalid token", 403);
