bookingChat.post("/api/chat", async (c) => {
  if (rateLimited3(postCounts2, getIp3(c), 10, 15 * 60 * 1e3)) {
    return c.json({ reply: "Too many messages. Please wait a few minutes and try again." }, 429);
  }
  const db = getDb(c.env);
  try {
    const body = await c.req.json();
    if (!body.message || body.message.length > 1e3) return c.json({ reply: "Invalid message." }, 400);
    const { message, history, system, businessName } = body;
    if (!c.env.CF_AI_TOKEN || !c.env.CF_ACCOUNT_ID) {
      return c.json({ reply: `Thanks for reaching out to ${businessName || "us"}! Please call us directly for immediate assistance.` });
    }
    const messages = [];
    if (history && Array.isArray(history)) {
      history.slice(-10).forEach((h) => messages.push({ role: h.role, content: h.content }));
    }
    messages.push({ role: "user", content: message });
    const cfRes = await fetch(`https://api.cloudflare.com/client/v4/accounts/${c.env.CF_ACCOUNT_ID}/ai/run/@cf/meta/llama-3-8b-instruct`, {
      method: "POST",
      headers: { Authorization: `Bearer ${c.env.CF_AI_TOKEN}`, "Content-Type": "application/json" },
      body: JSON.stringify({ messages: [{ role: "system", content: system || `You are a helpful assistant for ${businessName || "this business"}.` }, ...messages] })
    });
    const cfData = await cfRes.json();
    const reply = cfData?.result?.response || `Thanks for your question! Please call us directly for the best assistance.`;
    await db.connect();
    const chatClientId = await findClientIdByBusinessName(db, businessName);
    c.executionCtx.waitUntil(logAnalyticsEvent(db, chatClientId || businessName || "unknown", "chat", null, { businessName: businessName || null }));
    return c.json({ reply });
  } catch (err) {
    console.error("[/api/chat]", err);
    return c.json({ reply: "Sorry, I had trouble with that. Please call us directly." });
  } finally {
    await closeDb(db);
  }
});
