territoryPartner.post("/api/hub/change-password", async (c) => {
  const db = getDb(c.env);
  try {
    const token = c.req.header("x-hub-token");
    if (!token) return c.json({ error: "Unauthorized" }, 401);
    await db.connect();
    const result = await db.query(
      `SELECT * FROM territory_partner_applications WHERE hub_token = $1 AND status = 'approved' AND hub_token_expires_at > NOW()`,
      [token]
    );
    const partner = result.rows[0];
    if (!partner) return c.json({ error: "Invalid or expired token" }, 401);
    const { currentPassword, newPassword, confirmPassword } = await c.req.json();
    if (!currentPassword || !newPassword || !confirmPassword) return c.json({ error: "All password fields are required" }, 400);
    if (newPassword !== confirmPassword) return c.json({ error: "New passwords do not match" }, 400);
    if (newPassword.length < 8) return c.json({ error: "New password must be at least 8 characters" }, 400);
    if (!await bcryptjs_default.compare(currentPassword, partner.hub_password)) return c.json({ error: "Current password is incorrect" }, 401);
    const hashedPassword = await bcryptjs_default.hash(newPassword, 12);
    await db.query(`UPDATE territory_partner_applications SET hub_password = $1 WHERE id = $2 AND status = 'approved'`, [hashedPassword, partner.id]);
    return c.json({ success: true, message: "Password updated successfully" });
  } catch (error) {
    console.error("[hub change-password error]", error);
    return c.json({ error: "Password change failed" }, 500);
  } finally {
    await closeDb(db);
  }
});
territoryPartner.get("/api/hub/dashboard", async (c) => {
  const db = getDb(c.env);
  try {
    const token = c.req.header("x-hub-token");
    if (!token) return c.json({ error: "Unauthorized" }, 401);
    await db.connect();
    const partnerResult = await db.query(
      `SELECT * FROM territory_partner_applications WHERE hub_token = $1 AND status = 'approved' AND hub_token_expires_at > NOW()`,
      [token]
    );
    const partner = partnerResult.rows[0];
    if (!partner) return c.json({ error: "Invalid or expired token" }, 401);
    const clientsResult = await db.query(
      `SELECT * FROM clients WHERE data->>'partnerId' = $1 OR partner_id = $1 ORDER BY created_at DESC`,
      [String(partner.id)]
    );
    const clients = clientsResult.rows;
    const planPrices = {
      "website-only": 99,
      website_only: 99,
      "Website Only": 99,
      "website-blog": 129,
      website_blog: 129,
      "Website + Blog": 129,
      "website-blog-social": 159,
      "Website + Blog + Social": 159,
      "full-package": 218,
      "Full Package": 218
    };
    const totalMRR = clients.reduce((s, row) => {
      const plan = row.data?.selectedPlan || row.data?.plan || "";
      return s + (planPrices[plan] || 0);
    }, 0);
    const partnerMRR = Math.round(totalMRR * 0.6);
    return c.json({
      partner: {
        id: partner.id,
        name: partner.full_name,
        email: partner.email,
        tier: partner.tier,
        territory_name: partner.territory_name,
        territory_type: partner.territory_type,
        territory_zips: partner.territory_zips,
        territory_cities: partner.territory_cities,
        territory_counties: partner.territory_counties,
        territory_radius_center: partner.territory_radius_center,
        territory_radius_miles: partner.territory_radius_miles,
        industries: partner.industries,
        approved_at: partner.approved_at,
        hub_login_id: partner.hub_login_id
      },
      clients,
      totalMRR,
      partnerMRR
    });
  } catch (error) {
    console.error("[hub dashboard error]", error);
    return c.json({ error: "Failed to load dashboard" }, 500);
  } finally {
    await closeDb(db);
  }
});
